changeSet.sql:
ALTER TABLE ocr_job ADD CONSTRAINT ck_ocr_job_statut
    CHECK (statut IN ('EN_ATTENTE_OCR', 'EN_COURS_OCR', 'OCR_TERMINE', 'OCR_ECHEC'));
ALTER TABLE ocr_job ADD CONSTRAINT ck_ocr_job_langue
    CHECK (langue ~ '^(fra|ara)(\+(fra|ara))*$');
ALTER TABLE ocr_job ADD CONSTRAINT ck_ocr_job_tentatives CHECK (tentatives >= 0);
ALTER TABLE ocr_job ADD CONSTRAINT ck_ocr_job_bail
    CHECK (statut <> 'EN_COURS_OCR' OR (verrouille_par IS NOT NULL AND verrouille_jusqu_a IS NOT NULL));
-- Un seul job actif par version : un dépôt rejoué n'enfile pas deux fois.
CREATE UNIQUE INDEX uk_ocr_job_version_id_actif ON ocr_job (version_id)
    WHERE statut IN ('EN_ATTENTE_OCR', 'EN_COURS_OCR');
-- Réservation : jobs en attente, le plus ancien dépôt d'abord.
CREATE INDEX idx_ocr_job_depose_le_attente ON ocr_job (depose_le, prochaine_tentative_le)
    WHERE statut = 'EN_ATTENTE_OCR';
-- Reprise des baux expirés.
CREATE INDEX idx_ocr_job_verrouille_jusqu_a ON ocr_job (verrouille_jusqu_a)
    WHERE statut = 'EN_COURS_OCR';
